 CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE format( ''%s days %02d:%02d:%02d'', date_diff( ''day'', OplogClaimStart.start_time, OplogClaimEnd.end_time ), hour( OplogClaimEnd.end_time - OplogClaimStart.start_time ), minute( OplogClaimEnd.end_time - OplogClaimStart.start_time ), second( OplogClaimEnd.end_time - OplogClaimStart.start_time ) ) END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ and task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ and startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ and endstage.rn = 1 LEFT JOIN postgresql.ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN t12refined.camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN t12refined.camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN postgresql.ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER)"
    },
