UPDATE ui.dashboardresultset SET
vcdashboardresultsetschema = ' { 
    "Case ID":"integer",
    "Case creation time":"datetime",
    "Alert":"string",
    "Payer":"string",
    "Payee":"string",
    "VPA":"string",
